#!/usr/bin/env python3
"""# make_mb_v15.py (ledger #1598, cloned from make_mb_v14.py which stays as it is): the 6th argument MULU is the multiply LEVEL 0 to 3 (0 hk, 1 hm as before; 2 hq = sc_sys_v27 with the high half, 4 DSP per block; 3 hp = also the byte-store unit; both with byte/half loads and the fit search fed from registers; top sc_top_k7_v20, sc_block_v8, make_manifest_v4).  Levels 0 and 1 write the same files as make_mb_v14.py.
# make_mb_v14.py - make_mb_v13.py plus the multiply unit: a 6th argument MULU (0 or 1; 1 = the memory-mapped multiply unit, 3 DSP blocks per block; project name prefix hm; top sc_top_k7_v19, dispatcher sc_sys_v23, sc_block_v7; ledger #1584).  With MULU 0 it writes the same build as make_mb_v13.py.  Cloned from make_mb_v13.py (left as proven).
# make_mb_v13.py - make_mb_v8.py for the top sc_top_k7_v15 (dispatcher sc_sys_v18 AND far RAM in two banks, farram_bram_v2; ledger #1480); files named hh<NB>s<S>u1n1.  Cloned from make_mb_v8.py (left as proven)."""
#!/usr/bin/env python3
"""# make_mb_v6.py - make_mb_v5.py with the unit-less fix (ULW 0 gives FZ(0) NU(1), not NU(0); ledger #1466), files named hd... Cloned from make_mb_v5.py (left as proven; its unit-less builds hc4 / hc8 / hc2_s4 do not run jobs).
# make_mb_v6.py - like make_mb_v3.py but for the top sc_top_k7_v15 (status read inside the blocks: host_bridge_v12 + blk_rd_v1 + sc_top_k7_v15; ledger #1457). Files are named hn<NB>... Cloned from make_mb_v4.py (left as proven); the top is sc_top_k7_v15 (status AND command decode inside the blocks, ledger #1459), files named hc...
make_mb_v6.py - build files for the multi-block top sc_top_k7_v15 with the FUSION UNIT (ledger #1378): writes Makefile.fu<NB>_s<S>_u<W> and sc_k7_fu<NB>s<S>u<W>.v.
Usage:  python3 make_mb_v6.py 2 8 3 2    (NB blocks of S slices, units of 2**ULW lanes, NU units per block; ULW = 0: no unit, same logic as v15).
Then  S_CORE=... sh stage_mb_v2.sh   and   MAKEFILE=Makefile.fu2_s8_u8_n2 SEEDS="3 1 2" bash seeds_v1.sh     (inside the nix shell, in the build folder)"""
import sys, os
here = os.path.dirname(os.path.abspath(__file__))
nb = int(sys.argv[1]) if len(sys.argv) > 1 else 2
s = int(sys.argv[2]) if len(sys.argv) > 2 else 4
ulw = int(sys.argv[3]) if len(sys.argv) > 3 else 2
nu = int(sys.argv[4]) if len(sys.argv) > 4 else 2
imem = int(sys.argv[5]) if len(sys.argv) > 5 else 128
mulu = int(sys.argv[6]) if len(sys.argv) > 6 else 0
assert mulu in (0, 1, 2, 3), 'MULU is 0 to 3'
L = {0: 'hk', 1: 'hm', 2: 'hq', 3: 'hp'}[mulu]      # v11: code store words per block (block RAM, sc_sys_v21)
W = 1 << ulw
if ulw == 0: nu = max(nu, 1)      # v6 (ledger #1466): NU=0 breaks sc_sys_v17 (arrays [NU-1:0]); a unit-less build is FZ=0 with NU=1 (the unit is declared and never bound)
base = open(os.path.join(here, "Makefile.v2")).read()
assert "PROJECT = sc_k7_v2" in base and "rtl/sc_sys_v12.sv" in base and "rtl/sc_top_k7_v3.sv" in base and "rtl/host_bridge_v10.sv" in base
proj = "sc_k7_%s%ds%du%dn%di%d" % (L, nb, s, W, nu, imem)
units = (" rtl/uc_unitw%d.sv rtl/uc_unith%d.sv" % (W, W)) if ulw else ""
mk = (base.replace("PROJECT = sc_k7_v2", "PROJECT = %s" % proj)
          .replace("rtl/sc_sys_v12.sv", ("rtl/sc_sys_v27.sv rtl/fit_search_tree_v2.sv" if mulu >= 2 else (("rtl/sc_sys_v23.sv" if mulu else "rtl/sc_sys_v22.sv") + " rtl/fit_search_tree.sv")) + units)
          .replace("rtl/host_bridge_v10.sv", "rtl/host_bridge_v13.sv rtl/blk_rd_v2.sv rtl/blk_cmd_v1.sv")
          .replace("rtl/sc_top_k7_v3.sv", ("rtl/far_arb.sv rtl/sc_block_v8.sv rtl/sc_top_k7_v20.sv" if mulu >= 2 else "rtl/far_arb.sv rtl/sc_block_v7.sv rtl/sc_top_k7_v19.sv") if mulu else "rtl/far_arb.sv rtl/sc_block_v6.sv rtl/sc_top_k7_v18.sv").replace("rtl/farram_bram_v1.sv", "rtl/farram_bram_v2.sv"))
if mulu >= 2: mk = mk.replace("rtl/uc_core_v2v.sv", "rtl/uc_core_v2w.sv")      # v15: the core with byte/half loads
mk = "# Makefile.%s%d_s%d_u%d_n%d_i%d - GENERATED by make_mb_v15.py from Makefile.v2: %d blocks of %d slices, %d fusion units of %d lanes per block, %d code words per block (%s, project %s).\n" % (L, nb, s, W, nu, imem, nb, s, nu, W, imem, ("sc_top_k7_v20 with MULU %d" % mulu if mulu >= 2 else "sc_top_k7_v19 with MULU 1") if mulu else "sc_top_k7_v18", proj) + mk
open(os.path.join(here, "Makefile.%s%d_s%d_u%d_n%d_i%d" % (L, nb, s, W, nu, imem)), "w").write(mk)
top = ("// %s.v - GENERATED by make_mb_v6.py: the multi-block Kintex top with the fusion unit, %d blocks of %d slices, unit %d lanes.\n"
       "module top (input SYS_CLK, output [2:0] led);\n"
       "    %s #(.NB(%d), .S(%d), .QD(16), .IMEM_WORDS(%d), .DMW(16), .DSH(256), .SHL(14), .FZ(%d), .ULW(%d), .NU(%d)%s, .FAR_AW(16), .JK(32), .RXGAP(512)) u (.SYS_CLK(SYS_CLK), .led(led));\n"
       "endmodule\n") % (proj, nb, s, W, ("sc_top_k7_v20" if mulu >= 2 else "sc_top_k7_v19") if mulu else "sc_top_k7_v18", nb, s, imem, 1 if ulw else 0, ulw if ulw else 2, nu, (", .MULU(%d)" % mulu) if mulu else "")
open(os.path.join(here, "%s.v" % proj), "w").write(top)
print("wrote Makefile.%s%d_s%d_u%d_n%d_i%d and %s.v" % (L, nb, s, W, nu, imem, proj))
sys.path.insert(0, os.path.dirname(here))
import make_manifest_v4
mp, mf = make_manifest_v4.write(nb, s, ulw, nu, imem, mulu, outdir=here)
print("wrote " + os.path.basename(mp))
